def get_block(grid, row_start, col_start):
    rows = grid[row_start:row_start+3]
    return [[cols[col_start:col_start+3][i] for i in range(3)] for cols in rows]

from collections import Counter

# Check if any block has ONLY 5s
print("Blocks with only 5s (no non-5s):")
for i in range(7):
    for j in range(7):
        block = get_block(demo_input, i*3, j*3)
        vals = [v for row in block for v in row]
        if all(v == 5 for v in vals):
            print(f"Block[{i}][{j}] is pure 5s, output = {demo_output[i][j]}")
        elif any(v != 5 for v in vals):
            c = Counter()
            for row in block:
                for val in row:
                    if val != 5:
                        c[val] += 1
            if not c:
                print(f"Block[{i}][{j}] has non-5s Counter is empty!")

